
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_bop_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_bop", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.108011706754524e+00, -4.025564268692331e+00, -3.910063913704543e+00, -3.750123386535861e+00, -3.532291168507739e+00, -3.242562003677221e+00, -2.869924349351308e+00, -2.412573554005066e+00, -1.885680633980087e+00, -1.325286408401165e+00, -7.934583686956890e-01, -4.911170026657017e-01, -4.098049230526363e-01, -2.996754970533423e-01, -1.614879184961890e-01, -5.061041547405282e-02, -6.445426967828504e-03, -2.612787826807068e-04, -2.399189570241354e-06, -3.007658168256391e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


